import{_ as l,o,c as r,ag as i}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"『순수이성비판』 서문 — 문제의식","slug":"『순수이성비판』-서문-—-문제의식","link":"#『순수이성비판』-서문-—-문제의식","children":[]},{"level":2,"title":"합리주의와 경험론의 대립","slug":"합리주의와-경험론의-대립","link":"#합리주의와-경험론의-대립","children":[]},{"level":2,"title":"선험적/후험적, 분석적/종합적","slug":"선험적-후험적-분석적-종합적","link":"#선험적-후험적-분석적-종합적","children":[]},{"level":2,"title":"표상주의와 인식 기준의 문제","slug":"표상주의와-인식-기준의-문제","link":"#표상주의와-인식-기준의-문제","children":[]},{"level":2,"title":"칸트의 아이디어 — 코페르니쿠스적 전환","slug":"칸트의-아이디어-—-코페르니쿠스적-전환","link":"#칸트의-아이디어-—-코페르니쿠스적-전환","children":[]},{"level":2,"title":"감성과 지성","slug":"감성과-지성","link":"#감성과-지성","children":[]}],"relativePath":"philosophy/Epistemology/06. 칸트.md","filePath":"philosophy/Epistemology/06. 칸트.md"}'),n={name:"philosophy/Epistemology/06. 칸트.md"};function s(e,t,a,g,h,p){return o(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="『순수이성비판』-서문-—-문제의식" tabindex="-1">『순수이성비판』 서문 — 문제의식 <a class="header-anchor" href="#『순수이성비판』-서문-—-문제의식" aria-label="Permalink to &quot;『순수이성비판』 서문 — 문제의식&quot;">​</a></h2><p>이성은 특수한 운명을 지님: 거부할 수 없는 어떤 문제(형이상학적 문제)에 대한 관심을 갖고 있지만, 그 문제를 해결하지도 못함(이 또한 거부할 수 없는 사실). 칸트는 전통적 형이상학을 비판하고 대안으로 새로운 형이상학을 제시·비교하고자 함.</p><p>추론 능력은 전제로부터 결과를 이끌어낼 뿐 아니라, 결과로부터 전제를 끌어내는 힘도 있음 (인식의 근거를 찾으려는 능력).</p><h2 id="합리주의와-경험론의-대립" tabindex="-1">합리주의와 경험론의 대립 <a class="header-anchor" href="#합리주의와-경험론의-대립" aria-label="Permalink to &quot;합리주의와 경험론의 대립&quot;">​</a></h2><p>형이상학을 둘러싸고 **합리주의자(독단주의)**와 <strong>경험론자(회의주의)</strong> 사이의 싸움이 있었고, 이에 지친 <strong>무관심·무차별주의</strong>도 등장. 이 싸움은 결국 &quot;이성이라는 인식 능력의 원천이 어디인가&quot;의 문제 — 로크는 인식의 범위와 한계를 경험주의적 입장에서 제시하려 했음.</p><p><strong>형이상학이 학문으로 성공하지 못한 이유</strong>: 이미 학문으로 성공을 거둔 논리학·수학·자연과학과 달리, 형이상학은 그 정초(형식적/질료적)를 제대로 놓지 못함.</p><ul><li><strong>형식적 학문</strong> (예: 논리학): 사고의 법칙 등 형식에만 관심, 내용에는 무관심</li><li><strong>질료적 학문</strong>: 특수한 대상과 관련을 맺으며, 대상들 사이의 차이를 알아야 함</li><li>형이상학은 <strong>자연 형이상학</strong>과 <strong>도덕 형이상학</strong>으로 나뉨</li></ul><p>수학과 자연과학은 순전한 관찰자로만 머물지 않고 적극적인 <strong>기획</strong>(경험적 관찰만으로는 부족)을 통해 성공을 거둠 — 형이상학은 바로 이 지점, 즉 <strong>선험적이면서 종합적인 인식</strong>을 찾지 못해 실패함.</p><h2 id="선험적-후험적-분석적-종합적" tabindex="-1">선험적/후험적, 분석적/종합적 <a class="header-anchor" href="#선험적-후험적-분석적-종합적" aria-label="Permalink to &quot;선험적/후험적, 분석적/종합적&quot;">​</a></h2><ol><li><strong>선험적(a priori) / 후험적(a posteriori)</strong><ul><li>선험적: 경험으로부터 독립적 — 필연성, 보편성을 지님</li><li>후험적: 경험에 의존적</li></ul></li><li><strong>분석적(analytic) / 종합적(synthetic)</strong><ul><li>분석적: 주어 개념 안에 술어 개념이 이미 포함됨 — 인식을 확장하지 않고 명료하게 해줄 뿐 (예: &quot;총각은 미혼 남성이다&quot;)</li><li>종합적: 주어 개념에 술어 개념이 포함되어 있지 않음 — 인식을 확장함 (예: &quot;개는 노랗다&quot; — 일반적으로 어떤 경험이 필요)</li></ul></li><li><strong>기존 통념</strong>: 선험적인 것은 분석적이고, 후험적인 것은 종합적이라고 여겨짐 <ul><li>후험적이면서 분석적인 것은 개념적으로 불가능 (경험적이면서 동시에 분석판단인 것은 성립 불가)</li><li><strong>선험적이면서 종합적인 것은 가능함</strong> — 필연적·보편적이면서도, 주어 개념만으로는 술어 개념이 드러나지 않는 인식. 세계에 대한 새로운 정보를 알려주면서도 필연적·보편적인 것 → <strong>이를 드러내는 학문이 진정한 성공을 거둠</strong></li></ul></li></ol><p>(참고: [[05. 흄|흄의 포크]] 구도로 보면 — 관념들의 관계에 대한 지식(라이프니츠의 이성의 진리)은 필연적이며 관념 분석만으로 알 수 있고, 사실에 대한 지식(라이프니츠의 사실의 진리)은 우연적이며 분석만으로는 알 수 없음. 칸트는 이 구도에 &quot;선험적 종합판단&quot;이라는 제3의 범주를 추가하려는 것)</p><h2 id="표상주의와-인식-기준의-문제" tabindex="-1">표상주의와 인식 기준의 문제 <a class="header-anchor" href="#표상주의와-인식-기준의-문제" aria-label="Permalink to &quot;표상주의와 인식 기준의 문제&quot;">​</a></h2><p>마음(표상)과 외부세계(대상) 구도에서, <strong>표상주의</strong>는 표상을 매개로 대상을 인식함 — 그런데 표상과 대상이 일치하는지는 어떻게 확인하는가? 확인을 위한 기준이 표상세계 밖에 있다면 직접 인식할 수 없으므로, 그 기준은 표상세계 <strong>안에</strong> 존재해야 함.</p><ul><li>데카르트: 명석판명한 지각은 참 (다만 악령의 가설, 그리고 이를 보증하는 선한 신의 존재 문제가 남음)</li><li>경험주의: 기준이 되는 표상도 경험에서 비롯됨</li><li>합리주의: 기준이 되는 표상은 본유적임</li></ul><h2 id="칸트의-아이디어-—-코페르니쿠스적-전환" tabindex="-1">칸트의 아이디어 — 코페르니쿠스적 전환 <a class="header-anchor" href="#칸트의-아이디어-—-코페르니쿠스적-전환" aria-label="Permalink to &quot;칸트의 아이디어 — 코페르니쿠스적 전환&quot;">​</a></h2><p>칸트의 논의는 <strong>인식</strong>으로부터 출발함. 인식의 가능성의 조건은 곧 <strong>인식주체의 인식조건</strong>이며, 이는 인식주체의 인식조건에 대한 초월적 탐구를 통해 드러남. 즉 우리가 인식하는 것들 자체는 인식주체의 주관적 조건 때문에 &#39;그렇게&#39; 나타나는 것 — (과거에는 인식주체가 대상의 조건에 따라간다고 봤다면, 칸트는 반대로 대상이 인식주체의 조건에 따라 구성된다고 봄)</p><p><strong>현상(Phenomena)과 물자체(Ding an sich)의 구분</strong></p><ul><li>인식해야 할 대상들 = <strong>현상</strong></li><li><strong>물자체</strong>는 인식의 대상·목표가 아님 — 대상으로 주어지지 않은 것. 인식작용과 연관을 맺어 대상으로 주어졌을 때만 그것은 (물자체가 아니라) 현상으로서 인식됨</li></ul><h2 id="감성과-지성" tabindex="-1">감성과 지성 <a class="header-anchor" href="#감성과-지성" aria-label="Permalink to &quot;감성과 지성&quot;">​</a></h2><p>인식이 성립하려면 다음 두 가지가 <strong>반드시 함께</strong> 작동해야 함:</p><ol><li><strong>감성</strong>: 대상을 수용하는 능력 — 시공간이라는 형식을 통해 대상을 수용</li><li><strong>지성</strong>: 수용된 대상에 대해 사고하는 능력 — <strong>범주</strong>라는 지성적 조건을 통해 사고됨</li></ol><p>감성을 통해 대상이 수용되더라도, 지성의 범주를 통해 모종의 방식으로 사고되지 않으면 인식이 성립하지 않음(대상으로 인식되지 않음). 이 두 조건(시공간, 범주)을 따르지 않는 것은 애초에 인식 대상에 포함될 수 없음.</p><p><strong>의의</strong>: 시공간적으로 제한된 지식이라도 필연성·보편성을 확보할 수 있게 되어, 흄과 같은 전면적 회의주의를 받아들일 필요가 없어짐 — 초월적 관점에서 대상은 주관적(표상과 유사)이지만, 경험적 관점에서는 객관적임. 대상은 인식주체에 속해 있음(인식이 되어야 비로소 대상이 됨)이 동시에, 그 인식은 시공간·범주라는 정해진 방식에 따라 이루어짐.</p>',23)])])}const c=l(n,[["render",s]]);export{d as __pageData,c as default};
